#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupVersionTask final {
public:enum class Kind{Base,Minor,Full};enum class Stage{BaseChild,MinorTail,ReadFirst,RetainFirst,ReadMinor,ShiftFirst,ShiftSecond,ShiftThird,PrintMajor,Dot,PrintDot,CopyFraction,MaskFraction,AsciiFraction,PrintFraction,Return,MinorDot,MinorPrintDot,CopyMinor,PrintMinor,Complete};StartupVersionTask(Kind kind=Kind::Base,uint32_t source=0,uint8_t minor=0):kind_(kind),stage_(kind==Kind::Full?Stage::BaseChild:kind==Kind::Minor?Stage::MinorDot:Stage::ReadFirst),source_(source),minor_(minor){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}uint32_t source()const{return source_;}uint8_t major()const{return first_>>3;}uint8_t fraction()const{return first_&7;}uint8_t minor()const{return minor_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::BaseChild:return c.shortCall;case Stage::ReadFirst:return 5+c.read;case Stage::ReadMinor:return 3+c.read;case Stage::PrintMajor:case Stage::PrintDot:case Stage::PrintFraction:case Stage::MinorPrintDot:case Stage::PrintMinor:return c.call;case Stage::Return:return c.ret;default:return 3;}}template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::BaseChild:waiting_=true;break;case Stage::MinorTail:next=Stage::Complete;break;case Stage::ReadFirst:first_=uint8_t(read(false));break;case Stage::ReadMinor:minor_=uint8_t(read(true));break;case Stage::PrintMajor:case Stage::PrintDot:case Stage::PrintFraction:case Stage::MinorPrintDot:case Stage::PrintMinor:waiting_=true;break;case Stage::Return:next=Stage::Complete;break;default:break;}if(stage_==Stage::PrintMinor)next=Stage::Return;stage_=next;return cost;}
private:Kind kind_;Stage stage_;uint32_t source_;uint8_t first_=0,minor_=0;bool waiting_=false;};
class StartupBannerTask final {
public:enum class Stage{Label,PrintLabel,Version,PrintVersion,Input,WriteInput,SelectBank,WriteBank,RetainDelay,Settling,RetainInner,Delay,DecrementDelay,RepeatDelay,RestoreInner,DecrementSettling,RepeatSettling,RestoreDelay,ReadButtons,Release,WriteRelease,Output,WriteOutput,CompareButtons,SelectButtons,MinorVersion,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}bool secondDelay()const{return second_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Label:case Stage::Version:return 9;case Stage::PrintLabel:return c.call;case Stage::PrintVersion:case Stage::MinorVersion:return c.shortCall;case Stage::WriteInput:case Stage::WriteBank:case Stage::ReadButtons:case Stage::WriteRelease:case Stage::WriteOutput:return 4;case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::Settling:case Stage::Delay:return 6;case Stage::RestoreInner:case Stage::RestoreDelay:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::PrintLabel:case Stage::PrintVersion:waiting_=true;break;case Stage::WriteInput:write(true,0);break;case Stage::WriteBank:write(false,0x10);break;case Stage::Settling:settling_=second_?500:1;break;case Stage::Delay:delay_=2663;break;case Stage::DecrementDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::DecrementDelay;break;case Stage::DecrementSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::RestoreDelay:next=second_?Stage::Return:Stage::ReadButtons;break;case Stage::ReadButtons:buttons_=uint8_t(read());break;case Stage::WriteRelease:write(false,0x40);break;case Stage::WriteOutput:write(true,255);break;case Stage::SelectButtons:if(buttons_!=0xbf){second_=true;next=Stage::RetainDelay;}break;case Stage::MinorVersion:waiting_=true;second_=true;next=Stage::RetainDelay;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Label;bool second_=false,waiting_=false;unsigned settling_=0,delay_=0;uint8_t buttons_=0;};
}
